function fullCrate(){
 const base=crateItems(),taken=new Set(base.map(i=>i.id));
 const songs=music.songs.filter(x=>!taken.has(x.id)).map(x=>({id:'song:'+x.id,name:x.title,kind:x.file?'file':'demo',get:async()=>x.file?getEngine().ctx.decodeAudioData(await x.file.arrayBuffer()):x.get()}));
 return [...base.filter(i=>i.kind==='demo'),...songs,...base.filter(i=>i.kind!=='demo')];
}
const KIND_LABEL={demo:'Demo',file:'My file',project:'Project'};
const crateHue=text=>[...text].reduce((h,c)=>(h*31+c.charCodeAt(0))%360,7);
