export function splitSelection(){const S=useStore.getState();const ids=S.selection.clipIds.length?S.selection.clipIds:S.project.clips.map(c=>c.id);S.mutate('Split clips',p=>ids.forEach(id=>splitClipAt(p,id,S.transport.position)))}
export function deleteSelection(){const S=useStore.getState();S.mutate('Delete clips',p=>removeClips(p,S.selection.clipIds));S.select({clipIds:[]})}
export function duplicateSelection(){const S=useStore.getState();S.mutate('Duplicate clips',p=>duplicateClips(p,S.selection.clipIds))}
export function copySelection(cut=false){const S=useStore.getState();setClipboard(S.project.clips.filter(c=>S.selection.clipIds.includes(c.id)),S.project.tracks.map(t=>t.id));if(cut)deleteSelection()}
export function pasteSelection(){const S=useStore.getState();S.mutate('Paste clips',p=>pasteClipboard(p,S.transport.position,Math.max(0,p.tracks.findIndex(t=>S.selection.trackIds.includes(t.id)))))}
