  container.addEventListener('input',e=>{if(e.target.id==='dj-curve')useDJ.getState().set({curve:e.target.value});if(e.target.id==='dj-xf')useDJ.getState().set({xf:Number(e.target.value)});const i=Number(e.target.closest('[data-deck]')?.dataset.deck),d=e.target.dataset;if(d.deckValue)useDJ.getState().setDeck(i,{[d.deckValue]:Number(e.target.value)});if('deckEq'in d){const eq=[...useDJ.getState().decks[i].eq];eq[Number(d.deckEq)]=Number(e.target.value);useDJ.getState().setDeck(i,{eq})}});
