export async function studioAction(action){
 if(action==='stems'){const sel=useStore.getState().selection.clipIds;if(sel.length)await splitClip(sel[0]);else{toast('Pick a song to split into drums, bass, vocals and more.');await quickTask('stems')}}
 if(action==='split')splitSelection();if(action==='duplicate')duplicateSelection();if(action==='delete')deleteSelection();
 if(action==='add-track')useStore.getState().mutate('Add track',p=>p.tracks.push(makeTrack(p)));
 if(action==='reset-mix')useStore.getState().mutate('Reset mix',p=>{p.tracks.forEach(t=>{t.volume=1;t.pan=0;t.mute=false;t.solo=false});p.master.volume=1});
 if(action.startsWith('snap-pick:')){const slot=action.split(':')[1];if(mixSnaps[slot])recallSnap('Recall mix '+slot,mixSnaps[slot]);else{mixSnaps[slot]=captureMix();toast('Mix '+slot+' saved.');window.dispatchEvent(new Event('hitstudio:refresh'))}}
 if(action==='snap-clear'){mixSnaps={A:null,B:null};window.dispatchEvent(new Event('hitstudio:refresh'))}
 if(action==='auto-balance')await autoBalance();
 if(action.startsWith('snap-save:')){mixSnaps[action.split(':')[1]]=captureMix();toast('Mix snapshot saved.')}
 if(action.startsWith('snap-load:')){const snap=mixSnaps[action.split(':')[1]];if(snap)recallSnap('Recall mix',snap);else toast('Save a mix snapshot first.')}
 if(action==='create-play'){if(usePlaying.getState().playing)stopSeq();else{await music.setSource('create');await music.togglePlayback()}}
 if(action.startsWith('create-finish:')){const to=action.split(':')[1],bars=useCreate.getState().bounceBars,title=useCreate.getState().origin?.title||'My beat';
  if(to==='dj'){const buf=await renderLoopMix(bars);if(!buf){toast('Switch on at least one part first.');return}stopSeq();const entry=buffers.add(buf,`${title} (loop)`),st=useDJ.getState(),deck=st.decks[0].itemId&&!st.decks[1].itemId?1:0;useStore.getState().setMode('dj');await getDJ().load(deck,{id:`buf:${entry.id}`,name:entry.name,kind:'project',get:async()=>entry.buffer});toast(`Loaded on deck ${deck?'B':'A'}. Press Play.`);return}
  const n=await bounceToSong(bars);if(!n){toast('Switch on at least one part first.');return}stopSeq();useStore.getState().setMode(to==='mix'?'mix':'edit');await music.setSource('studio');
  if(to==='export')setTimeout(()=>document.querySelector('.topbar [data-action=export]')?.click(),200);else toast(`Added ${n} tracks to your ${to==='mix'?'mixer':'timeline'}.`)}
 if(action==='bounce'){const n=await bounceToSong(useCreate.getState().bounceBars);toast(`Added ${n} tracks to your arrangement.`);useStore.getState().setMode('edit');await music.setSource('studio')}
 if(action==='dj-demos'){const dj=getDJ();await Promise.all(fullCrate().filter(i=>i.kind==='demo').slice(0,2).map((item,i)=>dj.load(i,item)))}
 if(action==='dj-transition')await getDJ().smoothTransition();
 if(action==='dj-record'){const dj=getDJ();if(dj.recording){const seconds=dj.stopRecording();toast(`Recorded ${seconds.toFixed(1)} seconds into a new track.`)}else{if(music.source()!=='dj')await music.claimSource('dj');await dj.startRecording();toast('Recording DJ mix. Press Record mix again to finish.')}}
}
